CREATE DATABASE IF NOT EXISTS mnb_resort CHARACTER SET utf8mb4;
USE mnb_resort;
CREATE TABLE users(user_id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(100) NOT NULL, email VARCHAR(100) UNIQUE NOT NULL, phone VARCHAR(20), address VARCHAR(255) NULL, date_of_birth DATE NULL, user_role ENUM('Guest','Staff','Admin') DEFAULT 'Guest', is_active TINYINT(1) NOT NULL DEFAULT 1, password_hash VARCHAR(255) NOT NULL, profile_photo VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE accommodations(room_id INT AUTO_INCREMENT PRIMARY KEY, room_name VARCHAR(50) NOT NULL, category VARCHAR(50), description VARCHAR(500) NULL, amenities VARCHAR(500) NULL, capacity INT NOT NULL, rate_per_night DECIMAL(10,2) NOT NULL, is_available TINYINT(1) DEFAULT 1, is_archived TINYINT(1) DEFAULT 0, photo MEDIUMTEXT NULL);
CREATE TABLE reservations(reservation_id INT AUTO_INCREMENT PRIMARY KEY, guest_id INT NOT NULL, room_id INT NOT NULL, check_in_date DATE NOT NULL, check_out_date DATE NOT NULL, guest_count INT NOT NULL, status ENUM('Pending','Confirmed','Cancelled','Checked-In','Completed') DEFAULT 'Pending', payment_status ENUM('Unpaid','Partial','Paid') NOT NULL DEFAULT 'Unpaid', qr_code_hash VARCHAR(255) UNIQUE NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(guest_id) REFERENCES users(user_id), FOREIGN KEY(room_id) REFERENCES accommodations(room_id), INDEX(room_id,check_in_date,check_out_date));
CREATE TABLE messages(message_id INT AUTO_INCREMENT PRIMARY KEY, thread_id INT NOT NULL, sender_id INT NOT NULL, message_text TEXT NOT NULL, sent_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, is_read TINYINT(1) DEFAULT 0, is_archived TINYINT(1) DEFAULT 0, FOREIGN KEY(thread_id) REFERENCES users(user_id), FOREIGN KEY(sender_id) REFERENCES users(user_id));
CREATE TABLE notifications(notification_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, title VARCHAR(120) NOT NULL, message VARCHAR(500) NOT NULL, notification_type VARCHAR(40) NOT NULL DEFAULT 'announcement', reservation_id INT NULL, is_read TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE, FOREIGN KEY(reservation_id) REFERENCES reservations(reservation_id) ON DELETE SET NULL, INDEX(user_id,is_read,created_at));
CREATE TABLE favorites(user_id INT NOT NULL, room_id INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,room_id), FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE, FOREIGN KEY(room_id) REFERENCES accommodations(room_id) ON DELETE CASCADE);
CREATE TABLE payments(payment_id INT AUTO_INCREMENT PRIMARY KEY, reservation_id INT NOT NULL, amount DECIMAL(10,2) NOT NULL, payment_method VARCHAR(40) NOT NULL, transaction_type ENUM('Payment','Refund') NOT NULL DEFAULT 'Payment', status ENUM('Pending','Approved','Rejected') NOT NULL DEFAULT 'Approved', proof MEDIUMTEXT NULL, recorded_by INT NULL, paid_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(reservation_id) REFERENCES reservations(reservation_id) ON DELETE CASCADE, FOREIGN KEY(recorded_by) REFERENCES users(user_id) ON DELETE SET NULL);
CREATE TABLE reviews(review_id INT AUTO_INCREMENT PRIMARY KEY, reservation_id INT NOT NULL UNIQUE, guest_id INT NOT NULL, room_id INT NOT NULL, rating TINYINT NOT NULL, review_text VARCHAR(1000) NOT NULL, is_hidden TINYINT(1) NOT NULL DEFAULT 0, admin_reply VARCHAR(1000) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(reservation_id) REFERENCES reservations(reservation_id) ON DELETE CASCADE, FOREIGN KEY(guest_id) REFERENCES users(user_id) ON DELETE CASCADE, FOREIGN KEY(room_id) REFERENCES accommodations(room_id) ON DELETE CASCADE);
CREATE TABLE packages(package_id INT AUTO_INCREMENT PRIMARY KEY, item_type ENUM('Package','Add-on') NOT NULL DEFAULT 'Package', name VARCHAR(100) NOT NULL, description VARCHAR(500) NOT NULL, price DECIMAL(10,2) NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE resort_settings(setting_key VARCHAR(80) PRIMARY KEY, setting_value TEXT NOT NULL);
CREATE TABLE admin_activity(activity_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, action VARCHAR(120) NOT NULL, details VARCHAR(500) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE SET NULL, INDEX(created_at));
CREATE TABLE email_otps(otp_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, email VARCHAR(100) NOT NULL, purpose ENUM('register','reset','password_change') NOT NULL, code_hash VARCHAR(255) NOT NULL, full_name VARCHAR(100) NULL, phone VARCHAR(20) NULL, password_hash VARCHAR(255) NULL, attempts TINYINT UNSIGNED NOT NULL DEFAULT 0, expires_at DATETIME NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(email,purpose,created_at), INDEX(expires_at));
